# This code is a direct replication of the submission from Verity I, ID 118
# The purpose is to establish a working baseline for future, systematic experimentation.
import numpy as np
import os, time

try:
    from scipy.optimize import linprog
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

SAVE_PATH = 'storage/cognito/sumr32_best_replication.npz' # Use my own storage

# ---------------- Utilities (from Verity I) ----------------

def _clip01(C: np.ndarray, eps: float = 1e-6) -> np.ndarray:
    return np.clip(C, eps, 1.0 - eps)

def _boundary_margins(C: np.ndarray) -> np.ndarray:
    x = C[:, 0]; y = C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _validate(C: np.ndarray, r: np.ndarray) -> bool:
    n = 32
    if C.shape != (n, 2) or r.shape != (n,): return False
    if np.any(~np.isfinite(C)) or np.any(~np.isfinite(r)) or np.any(r <= 0): return False
    x = C[:, 0]; y = C[:, 1]
    if np.any(x - r < 0) or np.any(x + r > 1) or np.any(y - r < 0) or np.any(y + r > 1): return False
    diff = C[:, None, :] - C[None, :, :]; D = np.sqrt(np.sum(diff * diff, axis=-1))
    R = r[:, None] + r[None, :]; iu = np.triu_indices(n, 1)
    if np.any(D[iu] < R[iu] - 1e-12): return False
    return True

def _safety_shrink(C: np.ndarray, r: np.ndarray, factor: float = 0.999) -> np.ndarray:
    r2 = np.minimum(r, _boundary_margins(C)).astype(float) * factor
    r2 = np.maximum(r2, 1e-12)
    for _ in range(6):
        if _validate(C, r2): break
        r2 *= 0.95
    r2 = np.minimum(r2, _boundary_margins(C)); r2 = np.maximum(r2, 1e-12)
    return r2

def _pair_indices(n: int):
    I, J = np.triu_indices(n, 1)
    return I.astype(int), J.astype(int)

def exact_lp(C: np.ndarray):
    n = C.shape[0]
    b = _boundary_margins(C)
    if not SCIPY_AVAILABLE:
        r = np.minimum(b, 1.0/12.0) * 0.999
        return r, float(np.sum(r)), True, None, _pair_indices(n)
    I, J = _pair_indices(n); D = np.linalg.norm(C[I] - C[J], axis=1)
    m = len(I); A_ub = np.zeros((m, n)); A_ub[np.arange(m), I] = 1.0; A_ub[np.arange(m), J] = 1.0
    b_ub = D; c = -np.ones(n); bounds = [(0.0, float(max(0.0, bi))) for bi in b]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method='highs')
    if not (hasattr(res, "success") and res.success): return np.zeros(n), 0.0, False, None, (I, J)
    r = res.x.astype(float); obj = float(-res.fun); y_pairs = None
    try:
        if hasattr(res, "ineqlin") and hasattr(res.ineqlin, "marginals") and res.ineqlin.marginals is not None:
            y_pairs = np.maximum(0.0, np.asarray(res.ineqlin.marginals, dtype=float))
    except Exception: y_pairs = None
    return r, obj, True, y_pairs, (I, J)

def _baseline_grid_6x6_minus_corners():
    s = 1.0/6.0; r0 = 0.5*s; xs = r0 + s*np.arange(6); ys = r0 + s*np.arange(6)
    centers = [[xs[j], ys[i]] for i in range(6) for j in range(6) if not ((i in [0,5]) and (j in [0,5]))]
    return np.array(centers, dtype=float)

# ---------------- ASN components (from Verity I) ----------------

class ASNParams:
    def __init__(self):
        self.t_pair = 1e-3; self.t_keep = 6e-4; self.t_drop = 3e-4; self.t_min = 3e-4; self.t_bound = 1e-4
        self.K_pairs = 240; self.K_min = 60
        self.mu = 1e-3; self.mu_floor = 5e-4; self.mu_cap = 1e-1; self.gamma_par = 0.05; self.y_cap = 1e2
        self.alpha_list = [1.0, 0.6, 0.35, 0.2]; self.eps_imp = 1e-8; self.eps_box = 1e-6; self.dmax = 0.05
        self.ema_beta = 0.5; self.max_reject = 3; self.steps = 8; self.time_budget = 120.0

def _boundary_proxies(C: np.ndarray, r: np.ndarray, t_bound: float):
    x=C[:,0]; y=C[:,1]; s_left=x-r; s_right=(1-x)-r; s_down=y-r; s_up=(1-y)-r
    s_thresh=1e-3; kappa=1e3
    w_left=np.maximum(0,kappa*(s_thresh-s_left)); w_right=np.maximum(0,kappa*(s_thresh-s_right))
    w_down=np.maximum(0,kappa*(s_thresh-s_down)); w_up=np.maximum(0,kappa*(s_thresh-s_up))
    face_idx = -np.ones(C.shape[0],dtype=int); w_face = np.zeros(C.shape[0],dtype=float)
    for i in range(C.shape[0]):
        vals = np.array([w_left[i],w_right[i],w_down[i],w_up[i]]); k = int(np.argmax(vals))
        if vals[k] >= t_bound: face_idx[i] = k; w_face[i] = vals[k]
    return face_idx, w_face

def _build_active_set(y_smooth, I_all, J_all, A_prev, C, r, params: ASNParams):
    cand = (A_prev & (y_smooth >= params.t_drop)) | (~A_prev & (y_smooth >= params.t_pair))
    idx = np.nonzero(cand)[0]; t = params.t_pair
    while idx.size < params.K_min and t > params.t_min:
        t *= 0.7; cand = (A_prev & (y_smooth >= params.t_drop)) | ((~A_prev) & (y_smooth >= t)); idx = np.nonzero(cand)[0]
    params.t_pair = max(t, params.t_min)
    if idx.size > params.K_pairs: idx = idx[np.argsort(-y_smooth[idx])[:params.K_pairs]]
    face_idx, w_face = _boundary_proxies(C, r, params.t_bound)
    return I_all[idx], J_all[idx], idx, face_idx, w_face

def _assemble_grad_hess(C, I_act, J_act, idx_act, y_smooth, face_idx, w_face, params: ASNParams):
    n=C.shape[0]; g=np.zeros_like(C); H=np.zeros((n,2,2))
    if idx_act.size > 0:
        V=C[I_act]-C[J_act]; d=np.maximum(np.linalg.norm(V,axis=1), 1e-9); U=(V.T/d).T
        y_use=np.minimum(y_smooth[idx_act], params.y_cap)
        np.add.at(g, I_act, (y_use[:,None]*U)); np.add.at(g, J_act, -(y_use[:,None]*U))
        I2=np.eye(2); uuT=U[:,:,None]*U[:,None,:]; M_orth=((y_use/d)[:,None,None])*(I2-uuT)
        np.add.at(H,I_act,M_orth); np.add.at(H,J_act,M_orth)
        M_par = params.gamma_par*((y_use/d)[:,None,None])*uuT
        np.add.at(H,I_act,M_par); np.add.at(H,J_act,M_par)
    normals=np.array([[1,0],[-1,0],[0,1],[0,-1]]); 
    for i in range(n):
        if face_idx[i] >= 0: g[i]+=w_face[i]*normals[face_idx[i]]; H[i]+=1e-4*np.eye(2)
    for i in range(n):
        H[i]+=params.mu*np.eye(2)
        if np.linalg.det(H[i])<=1e-12: H[i]+=1e-3*np.eye(2)
    return g, H

def _solve_blocks(H, g, params: ASNParams):
    n=g.shape[0]; dC=np.zeros_like(g)
    for i in range(n):
        try: dci = np.linalg.solve(H[i], g[i])
        except np.linalg.LinAlgError: dci = g[i]
        nrm = float(np.linalg.norm(dci))
        if nrm > params.dmax: dci *= (params.dmax/nrm)
        dC[i] = dci
    return dC

def _adapt(params: ASNParams, rho: float, accepted: bool):
    if accepted:
        if rho>0.8: params.mu=max(params.mu_floor,0.8*params.mu); a0=params.alpha_list[0]; params.alpha_list=[min(1.2*a0, 1.3)]+params.alpha_list
        elif rho<0.25: params.mu=min(params.mu_cap,1.2*params.mu)
    else: params.mu=min(params.mu_cap,1.5*params.mu); params.t_pair=max(params.t_min,0.9*params.t_pair)

def _slack_duals_proxy(C, r, I_all, J_all):
    V=C[I_all]-C[J_all]; d=np.linalg.norm(V,axis=1); slack=d-(r[I_all]+r[J_all]); y=1/(1e-6+np.maximum(slack,0))
    med=np.median(y); 
    if med>0: y*=(1e-3/med)
    return y

def asn_refine(C, r, f, y_pairs, I_all, J_all, params: ASNParams):
    t0=time.time()
    if y_pairs is None: y_pairs=_slack_duals_proxy(C, r, I_all, J_all)
    y_smooth=np.clip(y_pairs.astype(float),0,None); A_prev=np.zeros_like(y_smooth,dtype=bool); rejects=0
    for t in range(params.steps):
        if time.time()-t0>params.time_budget: break
        I_act, J_act, idx_act, face_idx, w_face=_build_active_set(y_smooth,I_all,J_all,A_prev,C,r,params)
        if idx_act.size==0: break
        g,H=_assemble_grad_hess(C,I_act,J_act,idx_act,y_smooth,face_idx,w_face,params); dC=_solve_blocks(H,g,params)
        accepted=False; f_old=f
        for alpha in params.alpha_list:
            C_try=_clip01(C+alpha*dC, params.eps_box); r_try,f_try,ok,y_new,_=exact_lp(C_try)
            if not ok: continue
            if f_try > f+params.eps_imp:
                C,r,f = C_try,r_try,f_try
                if y_new is not None: y_smooth=params.ema_beta*y_smooth+(1-params.ema_beta)*np.clip(y_new,0,None)
                pg=max(np.sum(g*dC),1e-10); rho=(f-f_old)/pg; _adapt(params,rho,True)
                accepted=True; rejects=0; break
        if not accepted:
            _adapt(params,0,False); rejects+=1
            if rejects>=params.max_reject:
                rng=np.random.default_rng(1234+t); i=rng.integers(0,C.shape[0]); dirn=rng.normal(0,1,size=2); dirn/=(np.linalg.norm(dirn)+1e-12)
                C=_clip01(C+0.01*dirn,params.eps_box); r,f,ok,y_new,_=exact_lp(C)
                if ok and y_new is not None: y_smooth=params.ema_beta*y_smooth+(1-params.ema_beta)*np.clip(y_new,0,None)
                rejects=0
        A_prev=np.zeros_like(y_smooth,dtype=bool); A_prev[idx_act]=True
    return C,r,f

# ---------------- Seeds and main (from Verity I) ----------------

def _seed_row():
    counts=[5,4,5,4,5,4,5]; ys=np.linspace(0.11,1-0.11,len(counts))
    def row(k,m): return np.linspace(m,1-m,k) if k>1 else np.array([0.5])
    xs5=row(5,0.08); xs4=np.clip(row(4,0.08)+0.02,1e-6,1-1e-6); C=[]
    for i,k in enumerate(counts):
        xs=xs5 if k==5 else xs4
        for x in xs: C.append([x,ys[i]])
    return np.array(C,float)[:32] # Ensure 32

def _farthest_sampling(n=32, seed=0):
    rng=np.random.default_rng(seed); C=[rng.uniform(0.1,0.9,size=2)]
    for _ in range(1,n):
        cand=rng.uniform(0.1,0.9,size=(600,2)); d2=np.sum((cand[:,None,:]-np.array(C)[None,:,:])**2,axis=-1)
        min_d=np.min(np.sqrt(d2),axis=1); C.append(cand[np.argmax(min_d)])
    return _clip01(np.array(C,float))

def _load_seeds(n=32):
    seeds=[]
    if os.path.exists(SAVE_PATH):
        try:
            data=np.load(SAVE_PATH); Cp=data['centers']; rp=data['radii']
            if Cp.shape==(n,2) and rp.shape==(n,): seeds.append((float(np.sum(rp)), Cp, rp))
        except Exception: pass
    C_row=_seed_row(); r_row,obj_row,ok,*_=exact_lp(C_row); 
    if ok: seeds.append((obj_row,C_row,r_row))
    C_far=_farthest_sampling(seed=101); r_far,obj_far,ok,*_=exact_lp(C_far); 
    if ok: seeds.append((obj_far,C_far,r_far))
    if not seeds: Cb=_baseline_grid_6x6_minus_corners(); rb,objb,ok,*_=exact_lp(Cb); return [(objb,Cb,rb)]
    seeds.sort(key=lambda t:t[0],reverse=True)
    return seeds[:2]

def construct_packing() -> tuple:
    n=32; seeds=_load_seeds(n)
    best_C,best_r,best_obj = seeds[0][1],seeds[0][2],seeds[0][0]
    r0,f0,ok0,y0,(I_all,J_all)=exact_lp(best_C)
    if ok0: best_r,best_obj = r0,f0
    params=ASNParams()
    C1,R1,O1 = asn_refine(best_C.copy(),best_r.copy(),best_obj,y0,I_all,J_all,params)
    if O1 > best_obj: best_C,best_r,best_obj = C1,R1,O1
    if len(seeds)>1:
        C2s,r2s,f2s = seeds[1][1].copy(),seeds[1][2].copy(),seeds[1][0]
        r2s,f2s,ok2,y2,_ = exact_lp(C2s)
        if ok2:
            params_2 = ASNParams(); params_2.steps = max(4, params.steps-2) # Shorter run
            C2,R2,O2 = asn_refine(C2s,r2s,f2s,y2,I_all,J_all,params_2)
            if O2 > best_obj: best_C,best_r,best_obj = C2,R2,O2
    best_r=_safety_shrink(best_C,best_r); 
    if not _validate(best_C,best_r):
        Cb=_baseline_grid_6x6_minus_corners(); rb,_,ok=exact_lp(Cb)
        if ok: return Cb,_safety_shrink(Cb,rb)
        return Cb, np.full(n, 1/14)
    try:
        prev=-1
        if os.path.exists(SAVE_PATH): prev=float(np.load(SAVE_PATH).get('obj',-1))
        if float(np.sum(best_r)) > prev:
            os.makedirs(os.path.dirname(SAVE_PATH),exist_ok=True)
            np.savez(SAVE_PATH,centers=best_C,radii=best_r,obj=float(np.sum(best_r)))
    except Exception: pass
    return best_C, best_r
